/* hub.c: the window that replaces one entry of the watch's app list (the "slot", default World Clock, window 0x2b), and the apps it hosts.
 *
 * Two build modes (src/build_tennis.py): a single app takes the window over completely (HUB_MODE 0), or the window shows a native-style list of apps and opens the one you tap
 * (HUB_MODE 1). An app is an `App` (ui.h): name, icon, create, back, destroy. gen_apps.h (generated by src/watch/gen.py) includes the chosen apps and defines APPS[] and HUB_MODE.
 * Back gesture: the app gets it first (an overlay may close); if it does not use it, the app is closed (hub) or the window is left (single app, or the list).
 * Freestanding C: no libc, no libgcc, no static data (the window's state lives in one app-heap block). Firmware addresses: docs/symbols.csv. */
#include "ui.h"
#include "gen_apps.h"

#ifndef WINDOW_ID
#define WINDOW_ID 0x2b                                           /* the window this build replaces (build_tennis.py --slot passes it); 0x2b = World clock */
#endif
#define MAX_APPS 12
#define ROW_H 90                                                 /* the stock app list: rows 254 x 90, radius 26, 10 px apart, the first 6 px from the top; icon 64 x 64 at x 12; name 8 px right of it, 152 wide */
#define ROW_GAP 10

typedef struct {
    lv_obj_t *scr, *list, *root;                                 /* the screen, the list of apps (hub mode), the open app's container (the screen itself in single mode) */
    const App *cur; void *st;                                    /* the open app and its state (offset 16: src/emu tests read it) */
    lv_obj_t *row[MAX_APPS];
} Win;

static void open_app(Win *w, const App *a) {
    lv_obj_t *root = HUB_MODE ? mk_root(w->scr) : w->scr;
    void *st = a->create(root);
    if (!st) { if (HUB_MODE) lv_obj_del(root); return; }
    w->root = root; w->cur = a; w->st = st;
}
static void close_app(Win *w) {
    if (!w->cur) return;
    if (HUB_MODE) lv_obj_del(w->root);                           /* its widgets first, then the app's own cleanup */
    w->cur->destroy(w->st);
    w->cur = 0; w->st = 0; w->root = 0;
}
static void on_row(lv_event_t *e) {
    Win *w = (Win *)lv_event_get_user_data(e); lv_obj_t *t = lv_event_get_target(e);
    if (lv_event_get_code(e) != EV_CLICKED || w->cur) return;
    for (int i = 0; i < (int)NAPPS && i < MAX_APPS; i++) if (t == w->row[i]) { motor_once(1, 1); open_app(w, APPS[i]); return; }
}
static void on_screen(lv_event_t *e) {
    Win *w = (Win *)lv_event_get_user_data(e); u32 code = lv_event_get_code(e);
    if (code == EV_DELETE) { if (w->cur) w->cur->destroy(w->st); app_free(w); return; }
    if (code == EV_GESTURE && lv_indev_get_gesture_dir(lv_indev_get_act()) == 2) {
        if (w->cur && w->cur->back(w->st)) { }                   /* the app used the gesture */
        else if (HUB_MODE && w->cur) close_app(w);
        else wm_open(3, -1, 0, BACK_ANIM);
        ui_gesture_consume();
    }
}

/* world_create: first function of the image (--takeover-create gets its address | 1) */
__attribute__((section(".text.entry"))) lv_obj_t *world_create(u32 param, u32 param2) {
    (void)param; (void)param2;
    lv_obj_t *scr = lv_obj_create(0);
    Win *w = (Win *)app_malloc(sizeof(Win)); if (!w) return scr;
    fill8(w, 0, sizeof(Win)); w->scr = scr;
    *(void **)((u8 *)scr + 0x10) = w;                            /* lv_obj_t.user_data */
    lv_obj_clear_flag(scr, FL_SCROLLABLE); set_bg_color(scr, C_BLACK); set_bg_opa(scr, 255);
    if (HUB_MODE) {
        mk_text(scr, 0, 8, SCREEN_W, FT_NAME, C_WHITE, ALIGN_CENTER, "Applications");
        lv_obj_t *l = w->list = lv_obj_create(scr);
        lv_obj_set_size(l, SCREEN_W, SCREEN_H - 50); lv_obj_set_pos(l, 0, 50);
        set_bg_opa(l, 0); set_border_width(l, 0); set_radius(l, 0); set_pad_all(l, 0); lv_obj_set_scrollbar_mode(l, 0);
        for (int i = 0; i < (int)NAPPS && i < MAX_APPS; i++) {
            lv_obj_t *r = w->row[i] = mk_box(l, 1, 6 + i * (ROW_H + ROW_GAP), 254, ROW_H, 26, C_CARD);
            lv_obj_add_event_cb(r, on_row, 0, w);
            lv_obj_t *im = lv_img_create(r); lv_img_set_src(im, APPS[i]->icon); lv_obj_set_pos(im, 12, (ROW_H - 64) / 2);
            lv_obj_t *nm = mk_text(r, 0, 0, 152, FT_BTN, C_WHITE, ALIGN_LEFT, APPS[i]->name);          /* like the stock list: 152 wide, wraps onto a second line, centred beside the icon */
            lv_obj_update_layout(nm); lv_obj_align_to(nm, im, ALIGN_OUT_RIGHT_MID, 8, 0);
        }
    } else open_app(w, APPS[0]);
    lv_obj_add_event_cb(scr, on_screen, 0, w);                   /* 0 = LV_EVENT_ALL: gesture and DELETE (33) */
    return scr;
}

/* world_event(class, kind, data): the window manager's callback of the replaced window (docs/details.md, section 2). Every answer matters: the manager uses the return value.
 *   (0, 0)  window entered     -> remember the window id as the stock one did (wm_set_current)
 *   (0, 8)  key policy query   -> a bit mask. 0x2c4 is what the stock windows answer; with bit 6 set the manager sends the short press of the side key to the watch face
 *                                 by itself (wm_request(1, 2, ...)), exactly as in the stock apps, so we do nothing for the key.
 *   everything else -> 0. In particular the queries 6, 7 and 9 must be 0: a non-zero answer makes the manager run its own swipe-back with its own animation (docs/details.md).
 * The arguments arrive without sign or zero extension, so they are masked. */
__attribute__((section(".text.entry.event"))) u32 world_event(u32 cls, u32 kind, void *data) {
    (void)data; cls &= 0xff; kind &= 0xff;
    if (cls == 0 && kind == 0) { wm_set_current(WINDOW_ID); return 0; }
    if (cls == 0 && kind == 8) return 0x2c4;
    return 0;
}
